INSERT INTO package_itineraries (package_id, day_number, title, details) VALUES
(82, 1, 'Arrival and Welcome', 'Welcome to the destination! Check-in to your hotel, meet your guide, and get oriented with the area. Dinner at a local restaurant.'),
(82, 2, 'City Tour', 'Full day city tour including major landmarks, historical sites, and cultural attractions. Lunch included. Return to hotel by evening.'),
(82, 3, 'Adventure Activity', 'Experience thrilling adventure activities - choose from hiking, water sports, or zip-lining based on your preference. Safety briefing included.'),
(82, 4, 'Local Markets and Culture', 'Visit local markets, interact with artisans, and experience authentic local culture. Shopping time available. Traditional dinner.'),
(82, 5, 'Relaxation and Leisure', 'Free day to relax or pursue optional activities. Spa services available. Sunset viewing at a scenic location.'),
(82, 6, 'Farewell Dinner', 'Final evening with group dinner and cultural performance. Reflection on the trip and exchange contact information.'),
(82, 7, 'Departure', 'Leisurely breakfast, last-minute shopping, and transfer to airport/station for departure. Safe travels!');
